def choose_move(observation):
    # Defensive defaults
    # Try to read common fields safely; fall back to no-move if unclear.
    action = observation.get("action", None)
    grid = observation.get("grid", None)
    pos = observation.get("position", observation.get("pos", None))
    enemies = observation.get("enemies", [])
    resources = observation.get("resources", [])
    territory = observation.get("territory", [])
    width = observation.get("width", None)
    height = observation.get("height", None)

    # Helper to bound a move within -1..1
    def clamp1(n):
        return -1 if n < -1 else (1 if n > 1 else n)

    # If position not provided, stay
    if pos is None or not isinstance(pos, (list, tuple)) or len(pos) != 2:
        return [0, 0]

    x, y = pos

    # Simple defensive heuristics:
    # 1) If there is a resource nearby (dx,dy in [-1,0,1]), move towards it.
    best_dx, best_dy = 0, 0
    best_score = -10

    # Build candidate moves in a small neighborhood; score by proximity to resource, avoiding enemies.
    candidates = [(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1)]
    for dx, dy in candidates:
        nx, ny = x + dx, y + dy
        if dx == 0 and dy == 0:
            # zero move allowed
            pass
        # Bounds awareness if provided
        if width is not None and (nx < 0 or (isinstance(width, int) and nx >= width)):
            continue
        if height is not None and (ny < 0 or (isinstance(height, int) and ny >= height)):
            continue

        score = 0
        # Resource proximity
        if isinstance(resources, (list, tuple)):
            for r in resources:
                if isinstance(r, (list, tuple)) and len(r) >= 2:
                    rx, ry = r[0], r[1]
                    dist = max(abs(rx - nx), abs(ry - ny))
                    score += max(0, 4 - dist)
        # Enemy avoidance
        if isinstance(enemies, (list, tuple)):
            for e in enemies:
                if isinstance(e, (list, tuple)) and len(e) >= 2:
                    ex, ey = e[0], e[1]
                    dist = max(abs(ex - nx), abs(ey - ny))
                    if dist == 0:
                        score -= 5
                    else:
                        score -= max(0, 3 - dist)
        # Territory control / centrality heuristic
        if territory:
            # push toward center if grid size available
            cx, cy = x, y
            try:
                # approximate center if width/height known
                if width is not None and height is not None:
                    center_dx = (width - 1) / 2 - nx
                    center_dy = (height - 1) / 2 - ny
                    score += int((abs(center_dx) + abs(center_dy)) // 2 * -0.5)
            except Exception:
                pass

        if score > best_score:
            best_score = score
            best_dx, best_dy = dx, dy

    # If no movement improves score (e.g., deadlocked), default to staying or small safe move
    # Normal return
    return [best_dx, best_dy]

